using LittleLeo;
using UnityEngine;
using UnityEngine.Events;

namespace Astrea.RunModifiers;

[CreateAssetMenu(fileName = "StartOfBattleRunModifier", menuName = "Data/RunModifiers/StartOfBattleRunModifier", order = 0)]
public class StartOfBattleRunModifier : RunModifier
{
	[Header("Specifics")]
	[SerializeField]
	protected OmenLogicActionFace[] omenLogicActionFaces;

	public override void Initialize()
	{
		ReferenceSingleton<RunModifiersManager>.Instance.StartOfBattleRunModifierActions.Add(delegate
		{
			InvokeAlternatives.Invoke(ReferenceSingleton<CoroutineHandler>.Instance, 0.6f, GetStartOfBattleRunModifierAction());
		});
	}

	public virtual UnityAction GetStartOfBattleRunModifierAction()
	{
		return delegate
		{
			omenLogicActionFaces.InteractThroughItems(delegate(OmenLogicActionFace item)
			{
				item.OmenLogic.ActivateOmen(item.ActionFace.BattleAction, item.ActionFace.ActionValue, null, null);
			});
		};
	}

	public override string GetLocalizedDescription()
	{
		return base.localizationManager.GetLocalizedStartOfBattle() + base.localizationManager.GetLocalizedSpace() + GetAfterStartOfBattleDescription();
	}

	protected virtual string GetAfterStartOfBattleDescription()
	{
		ActionFace actionFace = omenLogicActionFaces.First().ActionFace;
		return actionFace.BattleAction.GetActionDescription(actionFace.ActionValue).LowercaseFirst();
	}
}
